// usage: p6 <rom> <replay.txt> <frames>
// prints: total ms/frame, worst frame ms + index, FNV hash of all framebuffers and audio.
use gba_emu::*;
use std::time::Instant;
fn main() {
    let a: Vec<String> = std::env::args().collect();
    let rom = std::fs::read(&a[1]).unwrap();
    let replay = std::fs::read_to_string(&a[2]).unwrap();
    let frames: u32 = a[3].parse().unwrap();
    let mut events: Vec<(u32, u32)> = replay
        .lines()
        .filter(|l| !l.starts_with('#') && !l.trim().is_empty())
        .map(|l| {
            let mut p = l.split_whitespace();
            (p.next().unwrap().parse().unwrap(), u32::from_str_radix(p.next().unwrap(), 16).unwrap())
        })
        .collect();
    events.reverse();
    let mut hash: u64 = 0xcbf29ce484222325;
    let mut mix = |v: u32| {
        hash ^= v as u64;
        hash = hash.wrapping_mul(0x100000001b3);
    };
    let mut worst = (0f64, 0u32);
    let start = Instant::now();
    unsafe {
        emu_init();
        std::ptr::copy_nonoverlapping(rom.as_ptr(), emu_rom_buffer(), rom.len());
        emu_load_rom(rom.len() as i32);
        for f in 0..frames {
            while let Some(&(ef, k)) = events.last() {
                if ef <= f {
                    emu_set_keys(k);
                    events.pop();
                } else {
                    break;
                }
            }
            let t = Instant::now();
            emu_run_frame();
            let ms = t.elapsed().as_secs_f64() * 1000.0;
            if ms > worst.0 {
                worst = (ms, f);
            }
            let px = std::slice::from_raw_parts(emu_framebuffer(), 240 * 160);
            for &p in px {
                mix(p);
            }
            let n = emu_audio_samples() as usize;
            let au = std::slice::from_raw_parts(emu_audio_buffer(), n * 2);
            for &s in au {
                mix(s as u16 as u32);
            }
        }
    }
    let total = start.elapsed().as_secs_f64() * 1000.0;
    println!("{:.2} ms/frame  worst {:.2} @{}  hash {:016x}", total / frames as f64, worst.0, worst.1, hash);
}

