        assert_eq!(bus.read16(0x0400_0004) & DISPSTAT_VCOUNT_FLAG, 0);
        bus.write16(0x0400_0004, 0);
        assert_ne!(bus.read16(0x0400_0004) & DISPSTAT_VCOUNT_FLAG, 0);
    }
}

