// Fuel meter: instrument a wasm so a global counts executed operators (wasmtime-style:
// nop/drop/block/loop/unreachable/return/else/end cost 0, the rest 1), then run a replay.
// usage: node fuel.js <wasm> <rom> <replay> <frames>  -> prints max/avg fuel per frame
const fs = require('fs');
const [wasmPath, romPath, replayPath, framesArg] = process.argv.slice(2);
const src = fs.readFileSync(wasmPath);

let pos = 0;
const u8 = () => src[pos++];
function uleb() { let r = 0, s = 0, b; do { b = src[pos++]; r += (b & 0x7f) * 2 ** s; s += 7; } while (b & 0x80); return r; }
function sleb() { let b; do { b = src[pos++]; } while (b & 0x80); }
function encU(n) { const out = []; do { let b = n & 0x7f; n = Math.floor(n / 128); if (n) b |= 0x80; out.push(b); } while (n); return out; }
function encS(n) { const out = []; for (;;) { let b = n & 0x7f; n >>= 7; if ((n === 0 && !(b & 0x40)) || (n === -1 && (b & 0x40))) { out.push(b); return out; } out.push(b | 0x80); } }

if (src.readUInt32LE(4) !== 1) throw 'bad';
pos = 8;
const sections = [];
while (pos < src.length) { const id = u8(); const size = uleb(); sections.push({ id, start: pos, end: pos + size }); pos += size; }

let importedGlobals = 0, ownGlobals = 0;
for (const s of sections) {
  pos = s.start;
  if (s.id === 2) { const n = uleb(); for (let i = 0; i < n; i++) { let l = uleb(); pos += l; l = uleb(); pos += l; const k = u8();
    if (k === 0) uleb(); else if (k === 1) { u8(); const f = u8(); uleb(); if (f & 1) uleb(); } else if (k === 2) { const f = u8(); uleb(); if (f & 1) uleb(); } else { u8(); u8(); importedGlobals++; } } }
  if (s.id === 6) ownGlobals = uleb();
}
const G = importedGlobals + ownGlobals;
const flush = (n, out) => { if (n) out.push(0x23, ...encU(G), 0x42, ...encS(n), 0x7c, 0x24, ...encU(G)); };

function instrumentBody(start, end) {
  pos = start;
  const out = [];
  const nLocals = uleb();
  for (let i = 0; i < nLocals; i++) { uleb(); u8(); }
  out.push(...src.subarray(start, pos));
  let pending = 0;
  while (pos < end) {
    const opStart = pos; const op = u8();
    const free = [0x01, 0x1a, 0x02, 0x03, 0x00, 0x0f, 0x05, 0x0b].includes(op);
    switch (op) {
      case 0x02: case 0x03: case 0x04: { const b = src[pos]; if (b === 0x40 || (b >= 0x6f && b <= 0x7f)) pos++; else sleb(); break; }
      case 0x0c: case 0x0d: case 0x10: case 0x20: case 0x21: case 0x22: case 0x23: case 0x24: case 0x25: case 0x26: case 0xd2: uleb(); break;
      case 0x0e: { const n = uleb(); for (let i = 0; i <= n; i++) uleb(); break; }
      case 0x11: uleb(); uleb(); break;
      case 0x1c: { const n = uleb(); pos += n; break; }
      case 0x3f: case 0x40: case 0xd0: pos++; break;
      case 0x41: case 0x42: sleb(); break;
      case 0x43: pos += 4; break;
      case 0x44: pos += 8; break;
      case 0xfc: { const sub = uleb(); if (sub === 8) { uleb(); pos++; } else if (sub === 10) pos += 2; else if (sub === 11) pos++; else if (sub === 12 || sub === 14) { uleb(); uleb(); } else if (sub >= 9) uleb(); break; }
      case 0xfd: throw 'simd';
      default: if (op >= 0x28 && op <= 0x3e) { uleb(); uleb(); } else if (!((op >= 0x45 && op <= 0xc4) || [0x00, 0x01, 0x05, 0x0b, 0x0f, 0x1a, 0x1b, 0xd1].includes(op))) throw 'op ' + op.toString(16);
    }
    if (!free) pending++;
    const control = [0x02, 0x03, 0x04, 0x05, 0x0b, 0x0c, 0x0d, 0x0e, 0x0f, 0x10, 0x11, 0x00].includes(op);
    if (control) { flush(pending, out); pending = 0; }
    out.push(...src.subarray(opStart, pos));
  }
  return out;
}

const outParts = [src.subarray(0, 8)];
const section = (id, body) => outParts.push(Buffer.from([id, ...encU(body.length)]), Buffer.from(body));
for (const s of sections) {
  pos = s.start;
  if (s.id === 6) {
    const n = uleb();
    section(6, [...encU(n + 1), ...src.subarray(pos, s.end), 0x7e, 0x01, 0x42, 0x00, 0x0b]);
  } else if (s.id === 7) {
    const n = uleb();
    section(7, [...encU(n + 1), ...src.subarray(pos, s.end), 4, ...Buffer.from('fuel'), 3, ...encU(G)]);
  } else if (s.id === 10) {
    const n = uleb(); const body = [...encU(n)];
    for (let i = 0; i < n; i++) { const size = uleb(); const st = pos; const fn = instrumentBody(st, st + size); pos = st + size; body.push(...encU(fn.length), ...fn); }
    section(10, body);
  } else outParts.push(Buffer.from([s.id, ...encU(s.end - s.start)]), src.subarray(s.start, s.end));
}
const instrumented = Buffer.concat(outParts.map(p => Buffer.from(p)));

const { instance } = new WebAssembly.Instance ? { instance: new WebAssembly.Instance(new WebAssembly.Module(instrumented), {}) } : null;
const e = instance.exports;
const rom = fs.readFileSync(romPath);
const events = fs.readFileSync(replayPath, 'utf8').split('\n').filter(l => l.trim() && !l.startsWith('#')).map(l => { const [f, k] = l.trim().split(/\s+/); return [+f, parseInt(k, 16)]; });
e.emu_init();
new Uint8Array(e.memory.buffer, e.emu_rom_buffer(), rom.length).set(rom);
e.emu_load_rom(rom.length);
const frames = +framesArg;
let ei = 0, max = 0n, maxAt = 0, total = 0n;
for (let f = 0; f < frames; f++) {
  while (ei < events.length && events[ei][0] <= f) e.emu_set_keys(events[ei++][1]);
  const before = e.fuel.value;
  e.emu_run_frame();
  e.emu_audio_samples();
  const used = e.fuel.value - before;
  total += used;
  if (used > max) { max = used; maxAt = f; }
}
console.log(`max ${(Number(max) / 1e6).toFixed(1)}M @${maxAt}  avg ${(Number(total / BigInt(frames)) / 1e6).toFixed(1)}M`);

