// Fuel meter: instrument a wasm so a global counts executed operators (wasmtime-style:
// nop/drop/block/loop/unreachable/return/else/end cost 0, the rest 1), then run a replay.
// usage: node fuel.js <wasm> <rom> <replay> <frames>  -> prints max/avg fuel per frame
const fs = require('fs');
const [wasmPath, romPath, replayPath, framesArg] = process.argv.slice(2);
const src = fs.readFileSync(wasmPath);

let pos = 0;
const u8 = () => src[pos++];
function uleb() { let r = 0, s = 0, b; do { b = src[pos++]; r += (b & 0x7f) * 2 ** s; s += 7; } while (b & 0x80); return r; }
function sleb() { let b; do { b = src[pos++]; } while (b & 0x80); }
function encU(n) { const out = []; do { let b = n & 0x7f; n = Math.floor(n / 128); if (n) b |= 0x80; out.push(b); } while (n); return out; }
function encS(n) { const out = []; for (;;) { let b = n & 0x7f; n >>= 7; if ((n === 0 && !(b & 0x40)) || (n === -1 && (b & 0x40))) { out.push(b); return out; } out.push(b | 0x80); } }

if (src.readUInt32LE(4) !== 1) throw 'bad';
pos = 8;
const sections = [];
while (pos < src.length) { const id = u8(); const size = uleb(); sections.push({ id, start: pos, end: pos + size }); pos += size; }

let importedGlobals = 0, ownGlobals = 0;
for (const s of sections) {
  pos = s.start;
  if (s.id === 2) { const n = uleb(); for (let i = 0; i < n; i++) { let l = uleb(); pos += l; l = uleb(); pos += l; const k = u8();
    if (k === 0) uleb(); else if (k === 1) { u8(); const f = u8(); uleb(); if (f & 1) uleb(); } else if (k === 2) { const f = u8(); uleb(); if (f & 1) uleb(); } else { u8(); u8(); importedGlobals++; } } }
  if (s.id === 6) ownGlobals = uleb();
}
