// usage: hot <rom> <frame>   (no keys) - histogram of PC (by 256-byte page) during that frame
use gba_emu::dma;
use gba_emu::gba::Gba;
use std::collections::HashMap;
fn main() {
    let a: Vec<String> = std::env::args().collect();
    let rom = std::fs::read(&a[1]).unwrap();
    let target: u32 = a[2].parse().unwrap();
    let mut gba = Gba::new(&rom);
    for _ in 0..5 + target {
        gba.run_frame();
    }
    let mut pages: HashMap<u32, u64> = HashMap::new();
    let mut steps = 0u64;
    let mut halted = 0u64;
    let mut dma_cycles = 0u64;
    let mut cycles = 0u64;
    let mut thumb = 0u64;
    while cycles < 280_896 {
        let pc = gba.cpu.registers[15];
        let was_halted = gba.bus.irq.halt_requested;
        if gba.cpu.cpsr & 0x20 != 0 {
            thumb += 1;
        }
        let mut c = gba.cpu.step(&mut gba.bus);
        let d = dma::run_pending_transfers(&mut gba.bus);
        c += d;
        dma_cycles += d as u64;
        // replicate advance_components through a frame call is private; emulate by run of 0? use public pieces
        gba_emu_advance(&mut gba, c);
        cycles += c as u64;
        steps += 1;
        if was_halted {
            halted += 1;
        } else {
            *pages.entry(pc >> 8).or_default() += 1;
        }
    }
    let mut v: Vec<_> = pages.into_iter().collect();
    v.sort_by_key(|x| std::cmp::Reverse(x.1));
    println!("steps {steps} halted {halted} thumb {thumb} dma_cycles {dma_cycles}");
    for (p, n) in v.iter().take(15) {
        println!("{:08x} {}", p << 8, n);
    }
}
fn gba_emu_advance(gba: &mut Gba, cycles: u32) {
    gba.advance_components_for_tools(cycles);
}

